"""contract/openapi.yaml, generated by scripts/build_openapi.py: stays in sync with the contract (this test
regenerates it in memory and fails if the committed file differs); names every route the app actually has (so a
new route added to apps/server without a matching path here is caught, not shipped undocumented); and, where it
can be checked mechanically, keeps each route's documented error statuses honest against its real dependencies
(every rate-limited route lists 401 and 429, every owner-only route lists 403, /health -- which has no rate
limiter -- lists neither 429 nor 529). Full per-route precision beyond that is scripts/build_openapi.py's own job
(see its "Adding a route" comment), not something a test can derive without reading the code itself."""

import importlib.util
import sys
from pathlib import Path
from typing import Any, Iterator

import pytest
import yaml
from fastapi.routing import APIRoute, APIWebSocketRoute
from openapi_spec_validator import validate as validate_openapi

from jeff.testing import FakeEngine

from jeff_server import auth, operations
from jeff_server.app import create_app
from jeff_server.mcp_mount import MCP_PATH, McpRoute
from jeff_server.settings import ServerSettings

ROOT = Path(__file__).resolve().parents[3]
OPENAPI_YAML = ROOT / "contract" / "openapi.yaml"

# /openapi.json serves this document; documenting it inside itself would be circular (see
# scripts/build_openapi.py's module docstring), so it is left out of both the document and this parity check.
SELF_DESCRIBING_ROUTE = "/openapi.json"
# The channel is a WebSocket, not an HTTP operation: OpenAPI has no way to describe it, so it is left out of the
# document's paths (info.description points to contract/socket.md) and out of this parity check.
CHANNEL_ROUTE = "/v1/channel"
# /mcp is the MCP SDK's streamable HTTP endpoint (JSON-RPC messages in POST bodies), a Starlette route rather than a
# FastAPI APIRoute: its messages are MCP's, not operations this document describes, so it is left out of the paths
# (info.description points to it) and out of this parity check.
MCP_ROUTE = MCP_PATH
# The console's own HTML page and static assets (jeff_server.console): no credentials at all (the page signs
# itself in) and not JSON operations -- they serve HTML and files, not something a request/response schema
# describes. Left out of the paths (info.description names them) and out of this parity check, for the same
# reason /openapi.json is.
CONSOLE_PAGE_ROUTES = {"/", "/ui", "/ui/", "/ui/assets/{name}"}


def _load_build_openapi() -> Any:
    """scripts/ is not an installed package; load scripts/build_openapi.py by its file path, the way this repo's
    other scripts (sync_shipped.py, record_golden.py) are run -- as standalone files, never imported."""
    spec = importlib.util.spec_from_file_location("build_openapi", ROOT / "scripts" / "build_openapi.py")
    assert spec is not None and spec.loader is not None
    module = importlib.util.module_from_spec(spec)
    sys.modules[spec.name] = module
    spec.loader.exec_module(module)
    return module


build_openapi = _load_build_openapi()


def _api_routes(routes: Any) -> Iterator[APIRoute]:
    """Every APIRoute of the app, through included routers (FastAPI 0.141 keeps an included router as one route
    holding the original router, rather than copying its routes into the app) -- the same helper
    apps/server/tests/test_auth.py uses."""
    for route in routes:
        if hasattr(route, "original_router"):
            yield from _api_routes(route.original_router.routes)
        elif isinstance(route, APIWebSocketRoute):
            continue  # WebSocket routes (the channel) are not HTTP operations; see CHANNEL_ROUTE
        elif isinstance(route, McpRoute):
            continue  # the MCP endpoint speaks MCP's JSON-RPC, not operations described here; see MCP_ROUTE
        elif isinstance(route, APIRoute):
            yield route
        else:
            raise AssertionError(f"The app has a route this parity check does not know: {route!r}; document it, "
                                 "or skip it here on purpose")


def _websocket_routes(routes: Any) -> Iterator[APIWebSocketRoute]:
    for route in routes:
        if hasattr(route, "original_router"):
            yield from _websocket_routes(route.original_router.routes)
        elif isinstance(route, APIWebSocketRoute):
            yield route


def _build_app() -> Any:
    settings = ServerSettings(engine_sockets=(Path("/tmp/jeff-openapi-test.sock"),), model_name="jeff-v1.3")
    return create_app(settings, engine=FakeEngine(lambda adapter, row: [1.0], set()))


def _dependency_calls(route: APIRoute) -> set[Any]:
    """Every callable in `route`'s solved dependency tree (router-level and path-level `dependencies=[...]`,
    plus each dependency's own sub-dependencies -- e.g. jeff_server.auth.limited's own Depends(authenticated)),
    so "does this route carry jeff_server.auth.limited / .owner" can be answered by introspecting the real route
    instead of re-deriving it by hand."""
    found: set[Any] = set()

    def walk(dependant: Any) -> None:
        if dependant.call is not None:
            found.add(dependant.call)
        for sub in dependant.dependencies:
            walk(sub)

    walk(route.dependant)
    return found


def _app_route_pairs() -> set[tuple[str, str]]:
    """Every (method, path) this server actually answers, lower-cased method, excluding HEAD (Starlette adds it to
    every GET for free; it is not a route of its own) and /openapi.json itself."""
    pairs: set[tuple[str, str]] = set()
    for route in _api_routes(_build_app().routes):
        if route.path == SELF_DESCRIBING_ROUTE or route.path in CONSOLE_PAGE_ROUTES:
            continue
        assert route.methods
        # path_format: the path as OpenAPI writes it, without a converter ({file_path:path} is {file_path}).
        pairs.update((method.lower(), route.path_format) for method in route.methods if method != "HEAD")
    return pairs


def _document_route_pairs(document: dict[str, Any]) -> set[tuple[str, str]]:
    return {(method, path) for path, item in document["paths"].items() for method in item}


def _document() -> dict[str, Any]:
    return yaml.safe_load(OPENAPI_YAML.read_text(encoding="utf-8"))


def test_generated_document_matches_the_committed_file() -> None:
    generated = build_openapi.build()
    committed = _document()
    assert generated == committed, "contract/openapi.yaml is stale; run: uv run python scripts/build_openapi.py"


def test_every_app_route_is_documented_and_no_more() -> None:
    assert _document_route_pairs(_document()) == _app_route_pairs()


def test_websocket_routes_are_skipped_and_the_channel_is_described_in_info() -> None:
    """The parity check above skips WebSocket routes on purpose: the only one is the channel, which OpenAPI cannot
    describe, so the document names it in info.description instead of under paths."""
    document = _document()
    assert [route.path for route in _websocket_routes(_build_app().routes)] == [CHANNEL_ROUTE]
    assert CHANNEL_ROUTE not in document["paths"]
    assert CHANNEL_ROUTE in document["info"]["description"]
    assert "contract/socket.md" in document["info"]["description"]


def test_the_mcp_route_is_skipped_and_described_in_info() -> None:
    """The parity check skips /mcp on purpose (see MCP_ROUTE); the document names it in info.description."""
    document = _document()
    assert [route.path for route in _build_app().routes if isinstance(route, McpRoute)] == [MCP_ROUTE]
    assert MCP_ROUTE not in document["paths"]
    assert "/mcp" in document["info"]["description"] and "Model Context Protocol" in document["info"]["description"]


def test_the_self_describing_route_is_deliberately_left_out() -> None:
    document = _document()
    assert SELF_DESCRIBING_ROUTE not in document["paths"]
    assert any(route.path == SELF_DESCRIBING_ROUTE for route in _api_routes(_build_app().routes))


def test_the_console_page_and_asset_routes_are_deliberately_left_out() -> None:
    document = _document()
    app_paths = {route.path for route in _api_routes(_build_app().routes)}
    for path in CONSOLE_PAGE_ROUTES:
        assert path not in document["paths"]
        assert path in app_paths
    assert "/ui/me" in document["paths"] and "/ui/examples" in document["paths"]  # the JSON endpoints ARE documented


def test_the_document_is_valid_openapi_3_1() -> None:
    validate_openapi(_document())  # raises on any structural problem


def test_every_response_body_is_the_standard_error_envelope_or_its_legacy_variant() -> None:
    """Every non-200 response on every path uses ErrorBody, except the two legacy routes (Task 7), which use
    LegacyErrorBody."""
    legacy_paths = {"/v1/systemone", "/v1/models"}
    for path, item in _document()["paths"].items():
        expected = "LegacyErrorBody" if path in legacy_paths else "ErrorBody"
        for method, operation in item.items():
            for status, response in operation["responses"].items():
                if status == "200":
                    continue
                ref = response["content"]["application/json"]["schema"]["$ref"]
                assert ref == f"#/components/schemas/{expected}", (path, method, status, ref)


# --- item 2: x-request-id on every response -----------------------------------------------------------------------

def test_every_response_carries_the_request_id_header() -> None:
    """Every response (the 200, and every error status) references the shared header component -- this server
    stamps x-request-id on literally everything it sends (jeff_server.app._Application)."""
    document = _document()
    assert document["components"]["headers"]["XRequestId"]["schema"]["pattern"] == "^[0-9a-f]{32}$"
    for path, item in document["paths"].items():
        for method, operation in item.items():
            for status, response in operation["responses"].items():
                assert response["headers"]["x-request-id"] == {"$ref": "#/components/headers/XRequestId"}, \
                    (path, method, status)


def test_error_responses_that_list_429_or_529_carry_retry_after() -> None:
    document = _document()
    for path, item in document["paths"].items():
        for method, operation in item.items():
            for status in ("429", "529"):
                response = operation["responses"].get(status)
                if response is not None:
                    assert "Retry-After" in response["headers"], (path, method, status)


def test_error_responses_that_list_401_carry_www_authenticate() -> None:
    document = _document()
    for path, item in document["paths"].items():
        for method, operation in item.items():
            response = operation["responses"].get("401")
            if response is not None:
                assert "WWW-Authenticate" in response["headers"], (path, method)


# --- item 1: per-route error statuses kept honest where mechanically possible --------------------------------------

def test_every_route_carrying_the_rate_limiter_lists_401_and_429() -> None:
    document = _document()
    for route in _api_routes(_build_app().routes):
        if route.path == SELF_DESCRIBING_ROUTE or auth.limited not in _dependency_calls(route):
            continue
        assert route.methods
        for method in route.methods:
            if method == "HEAD":
                continue
            responses = document["paths"][route.path_format][method.lower()]["responses"]
            assert "401" in responses and "429" in responses, (route.path, method)


def test_health_has_no_rate_limiter_and_lists_neither_429_nor_529() -> None:
    """The one route the review called out explicitly: /health has no rate limiter of any kind (unlike every
    other route) and must not advertise either of the two rate-limit-shaped statuses. (The mechanical converse of
    the test above -- "no rate limiter dependency implies no 429" -- would be wrong to assert for every route:
    POST /ui/login has its own sign-in lockout, jeff_server.users.SignInGuard, and legitimately lists 429 without
    ever carrying jeff_server.auth.limited.)"""
    responses = _document()["paths"]["/health"]["get"]["responses"]
    assert "429" not in responses and "529" not in responses


def test_every_owner_only_route_lists_403() -> None:
    document = _document()
    found_one = False
    for route in _api_routes(_build_app().routes):
        if route.path == SELF_DESCRIBING_ROUTE or operations.owner not in _dependency_calls(route):
            continue
        found_one = True
        assert route.methods
        for method in route.methods:
            if method == "HEAD":
                continue
            responses = document["paths"][route.path_format][method.lower()]["responses"]
            assert "403" in responses, (route.path, method)
    assert found_one  # the loop above is not vacuously true


# --- item 3: named oneOf variants, not a bare, unnamed oneOf --------------------------------------------------------

@pytest.mark.parametrize("name,required_key", [
    ("DecideCallsRequest", "calls"), ("DecideDispatchRequest", "dispatch"), ("DecideGraphRequest", "graph"),
    ("HealthStatusOnly", "status"), ("HealthReport", "status"),
])
def test_named_oneof_variants_have_a_title_and_require_their_distinguishing_key(name: str, required_key: str
                                                                                ) -> None:
    schema = _document()["components"]["schemas"][name]
    assert schema["title"] == name
    assert schema["additionalProperties"] is False
    assert required_key in schema["required"]


def test_decide_request_body_is_a_oneof_of_the_three_named_variants_with_no_discriminator() -> None:
    schema = _document()["paths"]["/v1/decide"]["post"]["requestBody"]["content"]["application/json"]["schema"]
    assert {ref["$ref"] for ref in schema["oneOf"]} == {
        "#/components/schemas/DecideCallsRequest", "#/components/schemas/DecideDispatchRequest",
        "#/components/schemas/DecideGraphRequest"}
    assert "discriminator" not in schema
    assert "no discriminator" in schema["description"].lower()


def test_health_response_is_a_oneof_of_the_two_named_variants_with_no_discriminator() -> None:
    schema = _document()["paths"]["/health"]["get"]["responses"]["200"]["content"]["application/json"]["schema"]
    assert {ref["$ref"] for ref in schema["oneOf"]} == {
        "#/components/schemas/HealthStatusOnly", "#/components/schemas/HealthReport"}
    assert "discriminator" not in schema
    assert "no discriminator" in schema["description"].lower()


def test_legacy_detail_oneof_names_its_object_shaped_alternative() -> None:
    detail = _document()["components"]["schemas"]["LegacyErrorBody"]["properties"]["detail"]
    shapes = [set(alt) for alt in detail["oneOf"]]
    assert {"type"} in shapes  # the plain string alternative, left inline -- nothing to name
    assert {"$ref"} in shapes
    ref = next(alt["$ref"] for alt in detail["oneOf"] if set(alt) == {"$ref"})
    assert ref == "#/components/schemas/LegacyModelErrorDetail"
    assert _document()["components"]["schemas"]["LegacyModelErrorDetail"]["title"] == "LegacyModelErrorDetail"


# --- item 6: manifest is not embedded as its own component; only the fragments functions_response needs are -----

def test_manifest_is_not_a_standalone_component() -> None:
    assert "manifest" not in _document()["components"]["schemas"]


def test_functions_response_embeds_the_manifest_fragments_it_needs_verbatim() -> None:
    """functions_response's labels/calibration/context/input/licence fields are not $refs any more (manifest is
    not embedded as a component to $ref into) -- they are the literal corresponding fragment of
    contract/schemas/manifest.schema.json, inlined. This checks that inlined copy against the fragment loaded
    directly from the source file, so the two can never silently drift apart. The manifest's own $refs into its
    $defs (a field's key and code_name) are inlined too; the listing adds that every field has its code_name."""
    manifest = yaml.safe_load((ROOT / "contract" / "schemas" / "manifest.schema.json").read_text())

    def inlined(node: Any) -> Any:
        if isinstance(node, dict):
            if set(node) == {"$ref"}:
                return inlined(manifest["$defs"][node["$ref"].removeprefix("#/$defs/")])
            return {key: inlined(value) for key, value in node.items()}
        return [inlined(item) for item in node] if isinstance(node, list) else node

    function = _document()["components"]["schemas"]["functions_response"]["properties"]["functions"]["items"]
    assert function["properties"]["labels"] == manifest["$defs"]["labels"]
    context, input = function["properties"]["context"]["allOf"], function["properties"]["input"]["allOf"]
    assert context == [inlined(manifest["properties"]["context"]),
                       {"type": "array", "items": {"required": ["code_name"]}}]
    assert input == [inlined(manifest["properties"]["input"]), {"required": ["code_name"]}]
    assert context[0]["items"]["properties"]["code_name"] == manifest["$defs"]["code_name"]
    assert function["properties"]["licence"] == manifest["properties"]["licence"]
    assert function["properties"]["calibration"]["oneOf"][1] == inlined(manifest["$defs"]["calibration"])


# --- item 4: /metrics content type, exactly as jeff_server.operations sends it --------------------------------------

def test_metrics_content_type_matches_what_the_server_actually_sends() -> None:
    content = _document()["paths"]["/metrics"]["get"]["responses"]["200"]["content"]
    assert set(content) == {"text/plain; version=0.0.4; charset=utf-8"}


@pytest.mark.parametrize("name", ["served_request", "adapters_response", "health_response", "login_request",
                                  "login_response"])
def test_new_schemas_are_registered_with_the_contract(name: str) -> None:
    """The small schemas Task 8 added for endpoints that previously had none (brief's context note): loaded and
    registered exactly like every other contract schema (packages/python/tests/test_contract.py already checks
    the full set of SCHEMAS matches every file in contract/schemas/)."""
    from jeff import contract

    assert name in contract.SCHEMAS
    assert contract.load_schema(name)["$id"] == f"https://jeff.dev/schemas/{name}.schema.json"
